const $=s=>document.querySelector(s);const quiz=$('#quiz-dialog'),info=$('#info-dialog');let step=0,answers=[],opener;
const questions=[{title:'O QUE VOCÊ PROCURA AGORA?',choices:[['autonomia','Aprender e seguir com mais autonomia'],['apoio','Conhecer um acompanhamento'],['indeciso','Ainda estou entendendo minhas opções']]},{title:'O QUE MAIS ATRAPALHA SUA ROTINA?',choices:[['direcao','Muita informação e pouca direção'],['comida','Organizar compras e alimentação'],['social','Manter a constância na vida social']]},{title:'COMO VOCÊ PREFERE COMEÇAR?',choices:[['pontual','Por um material simples e específico'],['completo','Pelo curso completo'],['conversa','Conversando sobre acompanhamento']]},{title:'QUAL PRÓXIMO PASSO FAZ MAIS SENTIDO?',choices:[['aprender','Conhecer um conteúdo para aprender'],['conversar','Conhecer as condições da consultoria'],['comparar','Comparar as opções com calma']]}];
function event(name,detail={}){document.dispatchEvent(new CustomEvent('endomonstro:event',{detail:{name,...detail}}))}
function openDialog(dialog,trigger){opener=trigger;dialog.showModal();document.body.style.overflow='hidden'}
function closeDialog(dialog){dialog.close();document.body.style.overflow='';if(opener?.isConnected)opener.focus()}
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>closeDialog(b.closest('dialog'))));[quiz,info].forEach(d=>{d.addEventListener('cancel',e=>{e.preventDefault();closeDialog(d)});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d)}})});
function renderQuestion(){const q=questions[step];$('#quiz-content').innerHTML=`<div class="quiz-progress" aria-hidden="true">${questions.map((_,i)=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div><span class="quiz-count">PERGUNTA ${step+1} DE 4</span><h2 id="quiz-title" tabindex="-1">${q.title}</h2><div class="quiz-options">${q.choices.map(([value,label],i)=>`<button class="quiz-choice" data-answer="${value}"><span>${String.fromCharCode(65+i)}</span>${label}</button>`).join('')}</div>${step?'<button class="quiz-back">← Voltar uma pergunta</button>':'<small>A indicação considera suas preferências. Não é uma avaliação de saúde.</small>'}`;$('#quiz-title').focus();$('#quiz-content').querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>{answers[step]=b.dataset.answer;answers.length=step+1;event('quiz_answer',{step:step+1,answer:b.dataset.answer});step++;step<questions.length?renderQuestion():renderResult()}));$('#quiz-content .quiz-back')?.addEventListener('click',()=>{step--;renderQuestion()})}
function resultFor(a){if(a[3]==='comparar')return'comparar';if(a[3]==='conversar'||a[2]==='conversa'||a[0]==='apoio')return'consultoria';if(a[2]==='pontual')return'essenciais';return'curso'}
function renderResult(){const result=resultFor(answers);const content={curso:{title:'SEU CAMINHO:<br><em>ENDOMONSTRO.</em>',text:'Você prefere aprender com conteúdo organizado. O curso reúne os três pilares: Como Fazer, Como Ser e Como Estar.',cta:'Conhecer o curso',target:'#curso'},consultoria:{title:'SEU CAMINHO:<br><em>UMA CONVERSA.</em>',text:'Você demonstrou interesse em acompanhamento. Conhecer o formato e as condições da consultoria é um próximo passo coerente.',cta:'Conhecer a consultoria',target:'#consultoria'},essenciais:{title:'UM PASSO<br><em>DE CADA VEZ.</em>',text:`Você prefere começar por uma necessidade específica. ${answers[1]==='comida'?'Cozinha da Tropa':answers[1]==='social'?'Rotina Social':'Guia Primeiros Passos'} é uma das propostas de materiais de entrada. Os Essenciais ainda não estão à venda; você pode conhecer as propostas e comparar com o curso.`,cta:'Conhecer os Essenciais',target:'#essenciais'},comparar:{title:'ESCOLHA<br><em>COM CLAREZA.</em>',text:'Você prefere entender as diferenças antes de decidir. Compare o conteúdo do Endomonstro com a possibilidade de conhecer a consultoria.',cta:'Comparar os dois caminhos',target:'#caminhos'}}[result];$('#quiz-content').innerHTML=`<span class="quiz-count">SEU RESULTADO</span><h2 id="quiz-title" tabindex="-1">${content.title}</h2><p class="result-note">${content.text}</p><a class="button result-link" href="${content.target}">${content.cta}<span aria-hidden="true">↗</span></a><button class="button outline" id="redo">Refazer as perguntas</button><small>A indicação usa somente suas respostas sobre preferências. Você pode escolher qualquer outro caminho.</small>`;$('#quiz-title').focus();$('.result-link').addEventListener('click',()=>{closeDialog(quiz);event('quiz_offer_click',{result});requestAnimationFrame(()=>{const target=$(content.target);target.setAttribute('tabindex','-1');target.focus({preventScroll:true})})});$('#redo').addEventListener('click',()=>{step=0;answers=[];renderQuestion()});event('quiz_complete',{result})}
document.querySelectorAll('[data-quiz]').forEach(b=>b.addEventListener('click',()=>{closeMenu();step=0;answers=[];openDialog(quiz,b);renderQuestion();event('quiz_start')}));
const products={primeiros:{title:'PRIMEIROS PASSOS.',text:'Uma proposta de guia para organizar seu início: entender o ponto de partida, reunir informações e planejar a rotina.',detail:'Foco: organização e primeiros passos.'},cozinha:{title:'COZINHA DA TROPA.',text:'Uma proposta de material sobre compras, organização e ideias de refeições simples, inspirada no conteúdo que Lucas compartilha.',detail:'Foco: praticidade na alimentação do dia a dia.'},social:{title:'ROTINA SOCIAL.',text:'Uma proposta de material para pensar as escolhas nos encontros, nos fins de semana e na volta à rotina.',detail:'Foco: continuidade e vida social.'}};
document.querySelectorAll('[data-product]').forEach(b=>b.addEventListener('click',()=>{const p=products[b.dataset.product];$('#info-content').innerHTML=`<span class="soon">EM BREVE</span><h2 id="info-title">${p.title}</h2><p>${p.text}</p><p>${p.detail}</p><small>Proposta de próximo lançamento. Conteúdo final, preço e disponibilidade ainda serão informados. Não há compra ou cadastro nesta janela.</small><a class="button" href="#curso" id="info-course">Enquanto isso, conheça o curso <span aria-hidden="true">↗</span></a>`;openDialog(info,b);$('#info-course').addEventListener('click',()=>closeDialog(info));event('essential_view',{product:b.dataset.product})}));
document.querySelectorAll('[data-consult]').forEach(b=>b.addEventListener('click',()=>{$('#info-content').innerHTML='<h2 id="info-title">BORA CONVERSAR<br><em>SOBRE SEU MOMENTO?</em></h2><p>O primeiro passo é conhecer o formato, as condições e a disponibilidade da consultoria.</p><p>Abra o perfil oficial de Lucas e envie uma mensagem dizendo que quer saber sobre a consultoria Endomonstro.</p><a class="button" href="https://www.instagram.com/lucas_cprot/" target="_blank" rel="noopener noreferrer">Abrir o Instagram do Lucas <span aria-hidden="true">↗</span></a><small>Nenhuma mensagem será enviada automaticamente. O contato acontece no Instagram.</small>';openDialog(info,b);event('consultoria_interest')}));
$('[data-privacy]').addEventListener('click',e=>{$('#info-content').innerHTML='<h2 id="info-title">SUA PRIVACIDADE.</h2><p>O quiz funciona nesta página, sem pedir cadastro. Suas respostas ficam apenas na memória desta aba e são descartadas quando a página é recarregada.</p><p>Esta versão não possui formulários de captura nem ferramentas de publicidade ou análise instaladas. Parâmetros de campanha presentes no endereço podem acompanhar o link para a Hotmart.</p><p>Ao abrir Instagram ou Hotmart, passam a valer as políticas de privacidade desses serviços. A plataforma de hospedagem pode registrar dados técnicos necessários para servir e proteger a página.</p>';openDialog(info,e.currentTarget)});
function closeMenu(){$('#mobile-menu').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').setAttribute('aria-label','Abrir menu')}
$('.menu-toggle').addEventListener('click',()=>{const open=$('#mobile-menu').hidden;$('#mobile-menu').hidden=!open;$('.menu-toggle').setAttribute('aria-expanded',String(open));$('.menu-toggle').setAttribute('aria-label',open?'Fechar menu':'Abrir menu')});$('#mobile-menu').querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
const params=new URLSearchParams(location.search);document.querySelectorAll('.checkout').forEach(a=>{const u=new URL(a.href);for(const key of ['utm_source','utm_medium','utm_campaign','utm_content','utm_term','src','sck']){const v=params.get(key);if(v)u.searchParams.set(key,v.slice(0,250))}a.href=u.href;a.addEventListener('click',()=>event('checkout_click',{product:'endomonstro'}))});
